package com.gomgomapps.math.core;
import java.util.*;
/** Index all nonnegative whole-number addition/subtraction conditions within a bound. */
final class BoundedWholeAddSub {
 private BoundedWholeAddSub(){}
 static boolean selected(String id,CurriculumLimits limits){return Set.of("add1000","sub1000").contains(id)&&!limits.hasWholeDigits()&&limits.wholeMaximum(-1)>=10000&&limits.givenMinimum(-1)==0;}
 static long count(int max){if(max<0||max>1000000)throw new IllegalArgumentException("whole bound");return (max+1L)*(max+2L)/2;}
 static int[] at(int max,long index){if(index<0||index>=count(max))throw new IndexOutOfBoundsException();int low=0,high=max;while(low<high){int mid=(low+high+1)/2;if(mid*(mid+1L)/2<=index)low=mid;else high=mid-1;}int part=(int)(index-low*(low+1L)/2);return new int[]{low,part};}
 static Question make(String id,int total,int part){if(!Set.of("add1000","sub1000").contains(id)||total<0||total>1000000||part<0||part>total)throw new IllegalArgumentException("whole condition");int a=id.equals("add1000")?part:total,b=id.equals("add1000")?total-part:part,answer=id.equals("add1000")?total:total-part;String expression=a+(id.equals("add1000")?" + ":" - ")+b;Question q=new Question(id,expression,expression,""+answer);q.kind="boundedWholeAddSub";ArithmeticTeaching.attach(q);return q.withInputs(a,b);}
 static Checker.Result check(Question q,List<String> answers){if(q.prompt==null||answers==null||answers.size()!=1||answers.get(0)==null)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"답 입력 필요");var m=java.util.regex.Pattern.compile("(0|[1-9][0-9]{0,6}) ([+−-]) (0|[1-9][0-9]{0,6})").matcher(q.prompt);if(!m.matches())return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제 확인 필요");int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(3));boolean add=q.skillId.equals("add1000");if(!Set.of("add1000","sub1000").contains(q.skillId)||add!=m.group(2).equals("+")||a>1000000||b>1000000||(!add&&a<b)||add&&a+b>1000000)return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"문제 확인 필요");String input=Expression.normalize(answers.get(0).trim());if(input.length()>120||!input.matches("[+-]?[0-9]+(?:\\.[0-9]+)?(?:/[+-]?[0-9]+)?"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");try{boolean correct=Expression.number(input).equals(Rational.of(add?a+b:a-b));return new Checker.Result(correct?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,correct?-1:0,correct?"정답":"이 답 확인");}catch(RuntimeException invalid){return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수로 입력 필요");}}
 static Question next(String id,Random random,CurriculumLimits limits,Map<String,Integer>recent){int max=limits.wholeMaximum(-1);long domain=count(max),start=Math.floorMod(random.nextLong(),domain);for(int i=0;i<Math.max(256,recent.size()+1);i++){int[] v=at(max,(start+i)%domain);Question q=make(id,v[0],v[1]);if(limits.allows(q)&&!recent.containsKey(q.signature()))return q;}throw new IllegalStateException("No fresh bounded whole condition");}
}
